Looking at the inference module, I see it has complex provider/model selection UI that's quite different from standard config fields. Let me convert it to be fully handled by the config module.

## 1. Remove UI Code from inference.module.js

**Remove these functions and their calls:**
- `showProviderSelection()`
- `buildFormTree()`
- `updateForm()`
- `saveForm()`
- `uiPicker()`

**Updated inference.module.js:**
```javascript
export const manifest = {
	name: "inference",
	context: ["service-worker"],
	version: "1.0.0",
	description: "Manages LLM inference across multiple providers with streaming support",
	dependencies: ["chrome-sync", "graph-db"],
	actions: ["prompt", "infer", "showProviderModule"],
	commands: [
		{ name: "call to inference", condition: input => input.startsWith('infer'), method: "infer" },
		{ name: "select inference model", keyword: "pick model", method: "openConfig" }
	]
};

let runtime, model, provider, providers = [];

export const initialize = async (rt) => {
	runtime = rt;
	await registerProviders();
	await loadConfig();
	(!provider || !model) && runtime.log('[Inference] No provider configured - use config UI');
};

export const openConfig = async () => {
	await runtime.call('config.showInferenceConfig');
};

// Keep all the core logic: registerProviders, loadConfig, saveConfig, prompt, etc.
// Remove: showProviderSelection, buildFormTree, updateForm, saveForm, uiPicker

export const getProviders = () => providers;
export const getCurrentConfig = () => ({ provider: provider?.manifest.name, model: model?.id });
export const setConfig = async (providerName, modelId) => {
	const selectedProvider = providers.find(p => p.manifest.name === providerName);
	const selectedModel = selectedProvider?.manifest.inferenceModels?.find(m => m.id === modelId);

	if (!selectedProvider || !selectedModel) {
		throw new Error('Invalid provider/model selection');
	}

	provider = selectedProvider;
	model = selectedModel;
	await saveConfig(providerName, modelId);
	runtime.log(`[Inference] ✅ Configured: ${provider.manifest.name} - ${model.name}`);
};
```

## 2. Extend config.module.js to Handle Inference

**Add to config.module.js:**
```javascript
export const manifest = {
	name: "config",
	context: ["extension-page"],
	// ... existing manifest
	actions: ["showConfig", "saveModuleConfig", "toggleCard", "resetToDefaults", "showInferenceConfig", "updateInferenceForm", "saveInferenceConfig"],
	uiComponents: [
		{ name: "module-config", getTree: "buildConfigTree" },
		{ name: "inference-config", getTree: "buildInferenceConfigTree" }
	]
};

let runtime, expandedCards = new Set(), inferenceConfigActive = false, selectedProvider = '';

// Add inference-specific state and functions
export const showInferenceConfig = async () => {
	inferenceConfigActive = true;
	const currentConfig = await runtime.call('inference.getCurrentConfig');
	selectedProvider = currentConfig.provider || '';
	await runtime.call('layout.addComponent', 'inference-config');
};

export const buildInferenceConfigTree = () => !inferenceConfigActive ? 
	{ tag: "div", text: "Inference config not active" } : {
	"inference-config-page": {
		tag: "div", style: "height: 100vh; display: flex; flex-direction: column; padding: 20px;",
		"header": {
			tag: "div", style: "display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px;",
			"back-button": { tag: "button", text: "← Back", class: "cognition-button-secondary", events: { click: "config.closeInferenceConfig" } },
			"title": { tag: "h2", text: "AI Provider Configuration", style: "margin: 0;" }
		},
		"config-card": {
			tag: "div", class: "cognition-card", style: "max-width: 600px;",
			"form": buildInferenceFormTree()
		}
	}
};

const buildInferenceFormTree = () => {
	const providers = runtime.call('inference.getProviders').catch(() => []);
	const selectedProviderObj = providers.find(p => p.manifest.name === selectedProvider);

	const providerOptions = [
		{ value: "", text: "Choose a provider..." },
		...providers.map(p => ({ 
			value: p.manifest.name, 
			text: `${p.manifest.name} (${p.manifest.inferenceModels?.length || 0} models)` 
		}))
	];

	const modelOptions = selectedProviderObj ? [
		{ value: "", text: "Choose a model..." },
		...selectedProviderObj.manifest.inferenceModels.map(m => ({ 
			value: m.id, 
			text: `${m.name} - ${m.bestFor?.slice(0, 2).join(', ') || 'General'}` 
		}))
	] : [{ value: "", text: "Select a provider first" }];

	return {
		tag: "form", events: { submit: "config.saveInferenceConfig" },
		"provider-section": {
			tag: "div", style: "margin-bottom: 20px;",
			"provider-label": { tag: "label", text: "AI Provider:", style: "display: block; margin-bottom: 8px; font-weight: 500;" },
			"provider-select": { 
				tag: "select", name: "provider", value: selectedProvider, required: true, 
				options: providerOptions, events: { change: "config.updateInferenceForm" }, 
				style: "width: 100%; padding: 8px; border: 1px solid var(--border-primary); border-radius: 4px;" 
			}
		},
		"model-section": {
			tag: "div", style: "margin-bottom: 20px;",
			"model-label": { tag: "label", text: "Model:", style: "display: block; margin-bottom: 8px; font-weight: 500;" },
			"model-select": { 
				tag: "select", name: "model", required: true, disabled: !selectedProviderObj,
				options: modelOptions,
				style: "width: 100%; padding: 8px; border: 1px solid var(--border-primary); border-radius: 4px;" 
			}
		},
		...(selectedProviderObj && {
			"info-section": {
				tag: "div", 
				style: "background: var(--bg-tertiary); padding: 12px; border-radius: 6px; margin-bottom: 20px; font-size: 14px;",
				text: `Provider: ${selectedProviderObj.manifest.name} | Available Models: ${selectedProviderObj.manifest.inferenceModels?.length || 0}`
			}
		}),
		"actions": {
			tag: "div", style: "display: flex; gap: 12px; justify-content: flex-end; padding-top: 16px; border-top: 1px solid var(--border-primary);",
			"cancel": { tag: "button", type: "button", text: "Cancel", class: "cognition-button-secondary", events: { click: "config.closeInferenceConfig" } },
			"save": { tag: "button", type: "submit", text: "Save Configuration", class: "cognition-button-primary", disabled: !selectedProvider }
		}
	};
};

export const updateInferenceForm = async (eventData) => {
	selectedProvider = eventData.target.value;
	await runtime.call('layout.renderComponent', 'inference-config');
};

export const saveInferenceConfig = async (eventData) => {
	eventData.preventDefault?.();
	const { provider, model } = eventData.formData;

	if (!provider || !model) {
		runtime.logError('[Config] Invalid inference selection');
		return;
	}

	try {
		await runtime.call('inference.setConfig', provider, model);
		await closeInferenceConfig();
		runtime.log(`[Config] ✅ Saved inference config: ${provider} - ${model}`);
	} catch (error) {
		runtime.logError('[Config] Failed to save inference config:', error);
	}
};

export const closeInferenceConfig = async () => {
	inferenceConfigActive = false;
	selectedProvider = '';
	// Component will be removed by layout system when user closes it
};
```

## 3. Update command routing

The inference module's `pick model` command now routes to the config module:

```javascript
commands: [
	{ name: "select inference model", keyword: "pick model", method: "openConfig" }
]
```

## Benefits of This Conversion

1. **Separation of Concerns**: Inference handles logic, config handles UI
2. **Consistency**: Inference config uses same styling as other configs  
3. **Layout Integration**: Users can position/resize the inference config component
4. **Simplified Inference**: Removes 200+ lines of UI code from inference module
5. **Centralized UI**: All configuration UI managed in one place

The config module now handles both generic module configs (via manifest schemas) and specialized configs like inference (via dedicated functions). This keeps the architecture clean while supporting complex UIs that don't fit generic patterns.

