import { configProxy } from './config.module.js';

export const manifest = {
	name: "inference",
	context: ["service-worker"],
	version: "1.0.0",
	description: "Manages LLM inference across multiple providers",
	dependencies: ["chrome-sync", "graph-db"],
	actions: ["prompt", "infer", "getProviderOptions", "getModelOptions"],
	commands: [
		{ name: "call to inference", condition: input => input.startsWith('infer'), method: "infer" }
	],
	config: {
		provider: { 
			type: 'select', 
			value: '', 
			label: 'AI Provider', 
			description: 'Select your preferred AI provider',
			options: [] // Populated dynamically during initialization
		},
		model: { 
			type: 'select', 
			value: '', 
			label: 'Model', 
			description: 'Select the AI model to use',
			options: [] // Populated based on selected provider
		}
	}
};

let runtime, providers = [];
const config = configProxy(manifest);

export const initialize = async (rt) => {
	runtime = rt;
	await registerProviders();
	await populateConfigOptions();
	validateCurrentConfig();
};

const registerProviders = async () => {
	providers = runtime.getModulesWithProperty('inferenceModels')
		.filter(p => ['makeRequest', 'getContent'].every(fn => typeof p[fn] === 'function'));
	runtime.log(`[Inference] Registered ${providers.length} providers`);
};

const populateConfigOptions = async () => {
	// Update provider options
	manifest.config.provider.options = [
		{ value: '', text: 'Select a provider...' },
